  tabs:[{id:'computer',type:'computer',title:'Computer'},{id:'overview',type:'overview',title:'Overview'},{id:'brief',type:'document',title:'Kickoff brief'}],activeTab:'computer',
  computer:{owner:'aaron',lastUsed:'aaron',paused:false,queue:['designers','slack'],completed:1},
